custom_css:
/*
* 主题名称：Book Extract - 《敲响这窄门》&《漫游者赠言》夜间护眼灰绿版
* 视觉风格：极简出版物、西式水印、阶梯式诗歌排版、竖排居中、交互天际线分离与收拢、隐形式卡片收尾、全宽屏正文
* 框架编写/整理：墨千尾（discord@这对吗/inkfoxxxx） | 二创重构：Vessel
* 核心逻辑：天地分离交互；Char与User文案/图片/寄语全面双轨分离；思维链高度截断与内滚动；版头题图横幅；空思维链防御。
* 借鉴声明：
*   1. 基础框架借用自：墨千尾/旅程美化置顶
*   2. 伪元素悬挂法与按钮轻量化借用自：旅程美化置顶
*   3. 提示词头部防隐形补丁借用自：blue
*   4. 编辑与更多按钮替换代码借用自：@qiyigeming
*   5. 宽屏正文代码借用自：@inkfoxxxx
*/

/* === 先导篇：字体导入 === */
/* 1. 正文与主UI字体：寒宋体 */
@import url("https://fontsapi.zeoseven.com/875/main/result.css");
/* 2. 扉页垫底水印字体：花体英文 (Dancing Script) */
@import url("https://fonts.googleapis.com/css2?family=Dancing+Script:wght@400;700&display=swap");

/* === 一、全局控制（利用变量自定义常见如文本颜色、边框颜色、自定义文案等） === */
:root {
  /* ------------------------------------ */
  /* ✏️ 【造物主控制台：自定义文案与URL专区】 ✏️ */
  /* 所有的文字、前缀、后缀、字体链接都在这里修改 */

  /* 1. 字体变量 */
  --font-main: "ChillHuoSong_F", serif; /* 主体中文字体 */
  --font-cursive: 'Dancing Script', cursive; /* 花体英文字体 */

  /* ==================================== */
  /* 👑 【Char / AI 角色视角专属配置】 👑 */
  /* ==================================== */
  --avatar-img-char: url('https://xffkws.iflytek.com/group1/M00/EF/C2/rB_aX2mp4TuASSDKAAKKD4U8dWo095.jpg'); /* Char 版头横幅图片 */
  --cover-title-char: "敲响这窄门";     /* Char 居中主标题 */
  --cover-subtitle-char: "Narrow Door"; /* Char 垫底的花体英文水印 */
  --author-prefix-char: "门◎";             /* Char 竖排名字顶部的前缀印记 */
  --footer-text-char: "「 窄门深锁，回声空荡 」"; /* Char 底部悬停隐形寄语 */

  /* ==================================== */
  /* 👤 【User / 玩家视角专属配置】 👤 */
  /* ==================================== */
  --avatar-img-user: url('https://openfs.oppomobile.com/open/oop/202603/06/d5772467d22a9208f72081b4dc6a3109.jpg'); /* User 版头横幅图片 */
  --cover-title-user: "漫游者赠言";       /* User 居中主标题 */
  --cover-subtitle-user: "Words of Rover"; /* User 垫底的花体英文水印 */
  --author-prefix-user: "途◎";             /* User 竖排名字顶部的前缀印记 */
  --footer-text-user: "「 漫游无尽，赠言无声 」"; /* User 底部悬停隐形寄语 */

  /* 3. 气泡中部：现代诗数据行（时间戳已隐藏） */
  --ui-floor-prefix: "踏足第 ";      /* 楼层前缀 */
  --ui-floor-suffix: " 步";          /* 楼层后缀 */

  --ui-time-prefix: "凝视第 ";       /* 生成时间前缀 */
  --ui-time-suffix: " 秒";           /* 生成时间后缀 */

  --ui-token-prefix: "落下第 ";      /* Token数前缀 */
  --ui-token-suffix: " 音";          /* Token数后缀 */

  /* 4. 输入框与按钮文案 */
  --input-placeholder: "书写赠言...";    /* 输入框空白提示词 */
  --load-more-text: "· 没入暗夜 ·";  /* 加载更多消息按钮文案 */
  /* 思维链折叠诗意文案 (使用 \A 实现 CSS 换行) */
  --reasoning-text: "我俯下身去吻她，只见她泪流满面，\A这刹那便决定了我的一生。";

  /* ------------------------------------ */
  /* 🎨 色彩美学基调（动态融合酒馆原生系统，夜间护眼灰绿调） */
  /* 背景不再写死，使用半透明遮罩与酒馆原生变量对接，跟随透明度 */
  --book-bg-hover: rgba(255, 255, 255, 0.03);  /* 暗色背景上的微光遮罩（用于卡片内背景/悬停/思维链） */
  --book-border: rgba(181, 194, 188, 0.15); /* 分割线与边框的冷灰（半透明装订线） */

  --ink-main: var(--SmartThemeBodyColor, #B5C2BC); /* 正文柔和冷灰（优先跟随酒馆设置，护眼不刺眼） */
  --ink-sub: #6C7A74;        /* 辅助信息深灰绿（时间、词符等） */
  --ink-accent: #5F8575;     /* 藏书印灰绿（用于门/途标志、高亮强调、悬停点亮） */
}

/* 定义全局字体与底色 */
body {
  font-family: var(--font-main);
  font-weight: normal;
  /* 彻底释放底层背景控制权，由酒馆原生设置接管 */
  color: var(--ink-main);
  letter-spacing: 0.02em;
}

/* 覆盖原生弹出面板等 UI 的颜色，解除死色封印 */
.drawer-content,
#table_drawer_content,
.options-content,
#bg_layer,
#chat {
  background-image: none !important;
  backdrop-filter: none !important;
  border-color: var(--book-border) !important;
  box-shadow: none !important;
}


/* ===== 二、顶栏（十字符咒：所有歧途都把我引向你） ===== */
#top-settings-holder {
  /* 顶栏背景同样释放，跟随酒馆原生面板底色 */
  background-color: var(--SmartThemeBlurTintColor) !important;
  border: none !important;
  border-bottom: 1px solid var(--book-border) !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
}

#top-bar {
  border-radius: 0 !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

/* 顶栏图标基础设置：替换为文字 */
#top-settings-holder .drawer-icon {
  opacity: 1;
  outline: none !important; /* 清除点击后的焦点框和状态残留 */
  -webkit-tap-highlight-color: transparent; /* 清除移动端点击闪烁 */
}
#top-settings-holder .drawer-icon::before {
  font-family: var(--font-main) !important;
  font-size: 1em;
  font-weight: normal;
  color: var(--ink-sub) !important;
  transition: color 0.8s ease-out, transform 0.8s ease-out;
  display: inline-block;
  vertical-align: middle;
}

/* 展开状态保持高亮 */
#top-settings-holder .drawer-icon.openIcon::before {
  color: var(--ink-accent) !important;
  transform: none !important;
}

/* 防卡死包裹：悬停效果 */
@media (hover: hover) {
  #top-settings-holder .drawer-icon:hover::before {
    color: var(--ink-accent) !important;
    transform: none !important;
    transition: color 0.6s ease-out;
  }
}

/* 点击（激活）时的物理反馈与形态蜕变 */
#top-settings-holder .drawer-icon:active::before {
  content: '◎' !important;
  transform: scale(0.75) !important;
  color: var(--ink-accent) !important;
  transition: transform 0.5s ease, color 0.5s ease !important;
}

/* 图标替换为诗意单字（所有歧途都把我引向你） */
.drawer-icon.fa-sliders.closedIcon::before, .drawer-icon.fa-sliders.openIcon::before { content: '所' !important; }
.drawer-icon.fa-plug.closedIcon::before, .drawer-icon.fa-plug.openIcon::before { content: '有' !important; }
.drawer-icon.fa-font.closedIcon::before, .drawer-icon.fa-font.openIcon::before { content: '歧' !important; }
.drawer-icon.fa-book-atlas.closedIcon::before, .drawer-icon.fa-book-atlas.openIcon::before { content: '途' !important; }
.drawer-icon.fa-user.closedIcon::before, .drawer-icon.fa-user.openIcon::before { content: '都' !important; }
.drawer-icon.fa-image.closedIcon::before, .drawer-icon.fa-image.openIcon::before { content: '把' !important; }
.drawer-icon.fa-cubes.closedIcon::before, .drawer-icon.fa-cubes.openIcon::before { content: '我' !important; }
.drawer-icon.fa-face-smile.closedIcon::before, .drawer-icon.fa-face-smile.openIcon::before { content: '向' !important; }
.drawer-icon.fa-address-card.closedIcon::before, .drawer-icon.fa-address-card.openIcon::before { content: '你' !important; }
.drawer-icon.fa-bars-progress.closedIcon::before, .drawer-icon.fa-bars-progress.openIcon::before { content: '引' !important; }


/* ===== 三、底栏（修复：输入框极简，图标微缩） ===== */
#send_form {
  /* 底栏背景释放，跟随聊天区颜色 */
  background-color: var(--SmartThemeChatTintColor) !important;
  border: none !important;
  border-top: 1px solid var(--book-border) !important;
  border-radius: 0 !important;
  /* 削减上下内边距，让底栏整体变矮 */
  padding: 4px 10px;
  box-shadow: none !important;
  min-height: auto !important;
}

#send_textarea {
  background-color: transparent !important;
  border: none !important;
  border-bottom: 1px dashed var(--book-border) !important;
  border-radius: 0 !important;
  font-family: var(--font-main);
  color: var(--ink-main) !important;
  /* 削减输入框本身的内边距与最小高度 */
  padding: 2px 5px 2px 15px;
  box-shadow: none !important;
  min-height: 24px !important;
  clip-path: none !important;
  transition: border-color 0.8s ease;
}
#send_textarea:focus {
  border-bottom: 1px solid var(--ink-accent) !important;
  outline: none !important;
}

/* 底栏图标：大幅缩小尺寸 */
#send_form [class*="fa-"]::before {
  color: var(--ink-sub) !important;
  font-size: 14px !important; /* 强制设为 14px */
  transition: color 0.8s ease;
}

/* 防卡死处理 */
@media (hover: hover) {
  #send_form [class*="fa-"]:hover::before {
    color: var(--ink-accent) !important;
  }
}


/* ===== 四、聊天区域（核武级解法：DOM融化与全流式排序） ===== */
#chat {
  padding: 20px 10px !important;
}

/* 1. 彻底融化原生双层容器壁垒 */
/* 这一步让名字、数据、正文全部变成同级兄弟，从而可以被统一排序！ */
.mes .mesAvatarWrapper,
.mes .mes_block {
  display: contents !important;
}

/* 2. 气泡卡片本体：化身为真正的 Flex 全局总指挥 */
.mes {
  position: relative !important;
  width: 100% !important;
  max-width: none !important;

  /* 天头留出 130px 给标题，地脚留出 55px 给隐形寄语与数字计数器 */
  padding-top: 130px !important;
  padding-bottom: 55px !important;
  margin: 0 0 25px 0 !important; /* 卡片底部的外部留白 */

  background: transparent !important;
  border: none !important;
  box-shadow: none !important;

  display: flex !important;
  flex-direction: column !important; /* 强制所有子元素纵向顺流排列 */
  align-items: center !important; /* 整体居中 */
  gap: 0px;
}

/* ---------------------------------------------------- */
/* 觉醒重构：复活头像容器化为无边框版头题图横幅 */
/* ---------------------------------------------------- */
.mes .avatar {
  display: flex !important;
  order: 0 !important; /* 排在最上面，也就是名字的上方 */
  width: 80% !important; /* 宽度适中，营造画幅呼吸感 */
  height: 40px !important; /* 窄窄的限制高度 */

  /* 物理下移核心：这里的 margin-bottom 会硬生生把下面的名字和正文全部往下推 */
  margin: 10px 0 40px 0 !important;

  padding: 0 !important;
  border: none !important; /* 彻底抹除边框 */
  border-radius: 0 !important;
  overflow: hidden !important;
  justify-content: center !important;
  align-items: center !important;
  background-color: transparent !important;
  box-shadow: none !important;
  z-index: 3;
}
/* 头像图片公共美学骨架 */
.mes .avatar img {
  display: block !important;
  width: 100% !important;
  height: 80px !important;
  object-fit: cover !important; /* 保证图片在窄框内不被压扁变形，而是裁切最美部分 */
  object-position: center center !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
/* ！！！头像图片URL双轨分离注入 ！！！ */
.mes[is_user="false"] .avatar img { content: var(--avatar-img-char) !important; }
.mes[is_user="true"] .avatar img { content: var(--avatar-img-user) !important; }


/* ---------------------------------------------------- */
/* 2. 扉页文案与交互天际线（天地分离布局） */
/* ---------------------------------------------------- */

/* 最高层级：编辑功能栏（撑满气泡高度，允许上下分化） */
.mes_buttons {
  position: absolute !important;
  top: 0px !important;
  bottom: 0px !important; /* 撑满高度，这是天地分离的基础 */
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;

  /* 容器事件穿透，防止撑满屏幕后阻挡正文文字的选中和点击 */
  pointer-events: none !important;

  /* 基因清洗：强制洗掉任何可能的竖排属性 */
  writing-mode: horizontal-tb !important;
  text-orientation: mixed !important;

  /* 稳固紧凑的横向骨架 */
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  justify-content: center !important;
  align-items: flex-start !important; /* 默认所有元素挂在天际线(顶部) */

  width: 100% !important; /* 撑满气泡宽度 */
  gap: 8px !important;

  opacity: 0.15; /* 极度克制，平时隐藏 */
  transition: opacity 0.8s ease;
  z-index: 10;
}
.mes:hover .mes_buttons {
  opacity: 1;
}

/* 恢复子元素物理交互，确保穿透的父容器里的按钮依然能点 */
.mes_buttons .mes_button,
.mes_buttons .favorite-toggle-icon,
.mes_buttons .mes_edit_buttons {
  pointer-events: auto !important;
}

/* 顶层小按钮基础尺寸修整 */
.mes_buttons .mes_button,
.mes_buttons .favorite-toggle-icon,
.mes_buttons .mes_edit_buttons .menu_button {
  writing-mode: horizontal-tb !important;
  text-orientation: mixed !important;
  background-color: transparent !important;
  padding: 0 4px !important;
  font-size: 0.9em !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  transition: transform 0.8s ease, opacity 0.8s ease;
}


/* ✏️ 【天际线上：编辑与更多】（代码作者：@qiyigeming，颜色由Loya适配为主题色） ✏️ */

/* 隐藏原图标 */
.mes_edit > i,
.extraMesButtonsHint > i {
    display: none !important;
}
/* 更改样式，可自行更换为url  */
.mes_edit::before,
.extraMesButtonsHint::before {
    display: block !important;
    font-size: 0.9rem;
    color: var(--ink-sub);
    font-weight: bold;
    text-shadow: none !important;
    font-family: var(--font-main);
    transition: color 0.8s ease;
}

.extraMesButtonsHint::before {
    content: '更多' !important;
}
.mes_edit::before {
    content: '修订' !important;
}

/* 悬停点亮 */
@media (hover: hover) {
    .mes:hover .mes_edit:hover::before,
    .mes:hover .extraMesButtonsHint:hover::before {
        color: var(--ink-accent) !important;
    }
}


/* ✏️ 【地平线下：翻页系统解耦与重构】 ✏️ */

/* --- 1. 左右翻页箭头（下沉，与隐形寄语共线） --- */
.mes .swipe_left,
.mes .swipe_right,
.mes .swipeRightBlock {
  position: absolute !important;
  bottom: 28px !important; /* 压低高度，寻找与寄语的同行基线 */
  z-index: 10;
  opacity: 0.15; /* 平时克制隐藏 */
  transition: opacity 0.8s ease;
  pointer-events: auto !important; /* 确保可点击 */
}
/* 悬停卡片时浮现 */
.mes:hover .swipe_left,
.mes:hover .swipe_right,
.mes:hover .swipeRightBlock {
  opacity: 1;
}

/* 左翻页箭头 */
.mes .swipe_left {
  left: 2% !important; /* 进一步向外缘推开 */
  transform: none !important; /* 清除原生偏移 */
}
.mes .swipe_left i,
.mes .swipe_left .fa-chevron-left {
  font-size: 0 !important;
}
.mes .swipe_left i::before,
.mes .swipe_left .fa-chevron-left::before {
  content: '上篇◎' !important;
  font-family: var(--font-main) !important;
  font-size: 13px !important;
  font-style: normal !important;
  letter-spacing: 0.05em;
  color: var(--ink-sub);
  white-space: nowrap;
  transition: color 0.8s ease;
}

/* 右翻页箭头 (兼容 swipeRightBlock) */
.mes .swipe_right,
.mes .swipeRightBlock {
  right: 2% !important; /* 进一步向外缘推开 */
  transform: none !important;
}
.mes .swipe_right i,
.mes .swipe_right .fa-chevron-right,
.mes .swipeRightBlock i,
.mes .swipeRightBlock .fa-chevron-right {
  font-size: 0 !important;
}
.mes .swipe_right i::before,
.mes .swipe_right .fa-chevron-right::before,
.mes .swipeRightBlock i::before,
.mes .swipeRightBlock .fa-chevron-right::before {
  content: '◎下篇' !important;
  font-family: var(--font-main) !important;
  font-size: 13px !important;
  font-style: normal !important;
  letter-spacing: 0.05em;
  color: var(--ink-sub);
  white-space: nowrap;
  transition: color 0.8s ease;
}

/* --- 2. 翻页数字（沉底，落在寄语下方居中） --- */
.mes .swipe_info,
.mes .swipes_counter {
  position: absolute !important;
  bottom: 5px !important; /* 沉落至最底端 */
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important; /* 绝对居中 */
  text-align: center !important;
  width: fit-content;
  font-family: var(--font-main) !important;
  font-size: 11px !important; /* 稍微缩小以符合下方辅助信息定位 */
  color: var(--ink-sub) !important;
  padding: 0 5px !important;
  z-index: 10;
  opacity: 0.15;
  transition: opacity 0.8s ease;
  pointer-events: auto !important;
}
.mes:hover .swipe_info,
.mes:hover .swipes_counter {
  opacity: 1;
}

/* 悬停点亮（防卡死包裹） */
@media (hover: hover) {
  .mes .swipe_left:hover i::before,
  .mes .swipe_left:hover .fa-chevron-left::before,
  .mes .swipe_right:hover i::before,
  .mes .swipe_right:hover .fa-chevron-right::before,
  .mes .swipeRightBlock:hover i::before,
  .mes .swipeRightBlock:hover .fa-chevron-right::before {
    color: var(--ink-accent) !important;
  }
}


/* ---------------------------------------------------- */
/* 2.5 封面文案双轨分离渲染 (Char / User) */
/* ---------------------------------------------------- */

/* a. 水印垫底公共美学骨架 */
.mes::after {
  position: absolute !important;
  top: 25px !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  text-align: center;
  font-family: var(--font-cursive);
  font-size: 5em;
  color: var(--ink-sub);
  opacity: 0.08;
  z-index: 1;
  white-space: nowrap;
  pointer-events: none;
  transition: color 0.8s ease, opacity 0.8s ease;
}

/* 悬停时，底纹染上强调色，由于是暗黑模式，透明度稍微调高一点保证能看见 */
.mes:hover::after {
  color: var(--ink-accent);
  opacity: 0.15;
}

/* 水印内容分离注入 */
.mes[is_user="false"]::after { content: var(--cover-subtitle-char); }
.mes[is_user="true"]::after { content: var(--cover-subtitle-user); }

/* b. 居中主标题公共美学骨架 */
.mes::before {
  position: absolute !important;
  top: 55px !important;
  left: 0 !important;
  right: 0 !important;
  margin: 0 auto !important;
  text-align: center;
  font-family: var(--font-main);
  font-size: 1.6em;
  letter-spacing: 0.4em;
  color: var(--ink-main);
  z-index: 2;
  white-space: nowrap;
  pointer-events: none;
}
/* 主标题内容分离注入 */
.mes[is_user="false"]::before { content: var(--cover-title-char); }
.mes[is_user="true"]::before { content: var(--cover-title-user); }


/* ---------------------------------------------------- */
/* 3. 内部元素文档流严密排序（Order 魔法全开） */
/* ---------------------------------------------------- */

/* --- Order 1：名字竖排居中 --- */
.mes .ch_name {
  order: 1 !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;

  /* 竖排魔法 */
  writing-mode: vertical-rl;
  text-orientation: upright;

  margin: 0 0 25px 0 !important; /* 与下方数据拉开一段呼吸距离 */
  padding: 0 !important;
  font-family: var(--font-main);
  font-size: 0.95em !important;
  font-weight: normal;
  color: var(--ink-main);
  letter-spacing: 0.2em; /* 竖排需加宽字距 */
  z-index: 3;
}
/* 严格只对 .ch_name 施加伪元素，断绝双重属性的可能，提取公共样式 */
.mes .ch_name::before {
  color: var(--ink-accent);
  font-size: 0.9em;
  margin-bottom: 12px; /* 竖排模式下，前缀的间距用 bottom推开 */
  letter-spacing: 0;
}
/* 名字前缀内容分离注入 */
.mes[is_user="false"] .ch_name::before { content: var(--author-prefix-char); }
.mes[is_user="true"] .ch_name::before { content: var(--author-prefix-user); }

/* --- Order 2, 3, 4：三行现代诗数据 --- */
/* 隐藏原生图标与时间戳 */
.mes .mesIDDisplay i,
.mes .mes_timer i,
.mes .tokenCounterDisplay i { display: none !important; }
.mes .timestamp { display: none !important; }

/* 统一基础样式 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
  display: block !important;
  width: 100%;
  text-align: center;
  font-family: var(--font-main);
  font-size: 0.75em !important;
  color: var(--ink-sub) !important;
  margin: 3px 0 !important;
  letter-spacing: 0.1em;
  opacity: 0.85;
  z-index: 3;
}
/* 强行排队 */
.mes .mesIDDisplay { order: 2 !important; }
.mes .mes_timer { order: 3 !important; }
.mes .tokenCounterDisplay {
  order: 4 !important;
  margin-bottom: 25px !important;
  border-bottom: 1px solid var(--book-border); /* 借用Token底部画出装订分割线 */
  padding-bottom: 25px !important;
}

/* 伪元素规范注入前后缀（带margin呼吸感） */
.mes .mesIDDisplay::before { content: var(--ui-floor-prefix); margin-right: 4px; }
.mes .mesIDDisplay::after { content: var(--ui-floor-suffix); margin-left: 4px; }

.mes .mes_timer::before { content: var(--ui-time-prefix); margin-right: 4px; }
.mes .mes_timer::after { content: var(--ui-time-suffix); margin-left: 4px; }

.mes .tokenCounterDisplay::before { content: var(--ui-token-prefix); margin-right: 4px; }
.mes .tokenCounterDisplay::after { content: var(--ui-token-suffix); margin-left: 4px; }


/* --- Order 5：思维链区块（限定 AI，安全居中） --- */
/* 使用 [is_user="false"] 排除用户卡片；恢复 display: block 保护内部 JS 结构 */
.mes[is_user="false"] details:has(.mes_reasoning_summary),
.mes[is_user="false"] .mes_block details {
  order: 5 !important;
  width: 85% !important; /* 限制宽度 */
  margin: 0 auto 20px auto !important; /* 物理 margin 绝对居中 */
  z-index: 3;
  display: block !important;
}


/* --- Order 7：正文区块 (宽屏释放) --- */
/* 宽屏代码借用自作者：@inkfoxxxx */
.mes .mes_text {
  order: 7 !important;
  line-height: 1.85 !important;
  color: var(--ink-main);

  width: 100% !important;
  padding: 0px !important;
  margin: 0 !important;

  text-align: justify;
  z-index: 3;
}
/* 文字细节排版 */
.mes_text p { margin-bottom: 1.2em !important; }

/* 强制斜体文字竖直，使用 !important 压制原生 Markdown 渲染 */
.mes_text i, .mes_text em {
  font-style: normal !important;
  color: var(--ink-sub);
}

.mes_text blockquote {
  margin: 1.5em 0 !important;
  padding: 10px 15px !important;
  background-color: var(--book-bg-hover); /* 跟随背景的半透明遮罩叠加 */
  border-left: 3px solid var(--ink-accent); /* 引用线使用强调色 */
  color: var(--ink-main);
  font-size: 0.95em;
  border-radius: 0;
}
.mes_text b, .mes_text strong {
  font-weight: normal;
  color: var(--ink-accent);
  border-bottom: 1px solid var(--book-border);
}

/* 消除最后一条消息的异常留白，使其贴近底栏输入框 */
.mes.last_mes {
  margin-bottom: 0px !important;
}
.mes.last_mes .mesAvatarWrapper {
  padding-bottom: 0px !important;
}


/* ===== 五、滚动条（上下滑动的）+滑动条 ===== */
/* 滚动条极简隐形 */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
  background-color: transparent;
}
::-webkit-scrollbar-track {
  background-color: transparent;
}
::-webkit-scrollbar-thumb {
  background-color: var(--book-border);
  border-radius: 10px;
  border: none;
  box-shadow: none !important;
}
::-webkit-scrollbar-thumb:hover {
  background-color: var(--ink-sub);
}

/* 滑动条克制设计 */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  background: transparent !important;
  cursor: pointer;
}
input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 2px;
  background: var(--book-border);
  border-radius: 0px;
  border: none;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  margin-top: -6px;
  height: 14px;
  width: 6px;
  background-color: var(--ink-main);
  border: none;
  border-radius: 0;
  box-shadow: none;
  transition: transform 0.8s ease;
}
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
  transform: scale(1.2);
  background-color: var(--ink-accent);
}

/* 兼容Firefox浏览器 */
input[type="range"]::-moz-range-track {
  height: 2px;
  background: var(--book-border);
  border-radius: 0px;
  border: none;
}
input[type="range"]::-moz-range-thumb {
  height: 14px;
  width: 6px;
  background-color: var(--ink-main);
  border: none;
  border-radius: 0;
}


/* ===== 六、输入框提示文字自定义 ===== */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: transparent !important;
  text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--input-placeholder); /* 调用变量 */
  color: var(--ink-sub);
  position: absolute;
  /* 精准绝对居中 */
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-main);
  /* 缩小底栏提示词字号 */
  font-size: 0.75em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}


/* ===== 七、正则+脚本易读+防误触 ===== */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 5px 10px;
  border-radius: 4px;
  margin-bottom: 5px;
  background: var(--book-bg-hover);
  border: 1px solid var(--book-border);
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100%;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  word-break: break-word;
  font-weight: normal;
  font-size: 1.05em;
  color: var(--ink-main);
}

.regex-script-label.flex-container > .flex-container.flexnowrap,
.script-item .script-item-control {
  width: 100%;
  justify-content: flex-start;
}


/* ===== 八、“加载更多消息”美化（图书翻页感） ===== */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important;
  display: block;
  padding: 8px 30px;
  margin: 30px auto;
  width: fit-content;
  background-color: transparent;
  border: 1px solid var(--book-border);
  border-radius: 50px;
  box-shadow: none;
  cursor: pointer;
  transition: all 0.8s ease;
}
#show_more_messages::before {
  content: var(--load-more-text); /* 调用变量 */
  font-family: var(--font-main);
  font-size: 13px !important;
  color: var(--ink-sub) !important;
  letter-spacing: 0.2em;
  text-shadow: none;
  transition: color 0.8s ease;
}
@media (hover: hover) {
  #show_more_messages:hover {
    background-color: var(--book-bg-hover);
    border-color: var(--ink-sub);
  }
  #show_more_messages:hover::before {
    color: var(--ink-main) !important;
  }
}


/* ===== 九、思维链美化（高度截断、隐式滚动与空壳防御） ===== */
/* 定义带有失焦感的深长呼吸动画，阴影色适配夜间护眼的灰绿 */
@keyframes poetic-breathing {
  0% { opacity: 0.2; filter: blur(1px); }
  50% { opacity: 1; filter: blur(0px); text-shadow: 0 0 3px rgba(95, 133, 117, 0.4); }
  100% { opacity: 0.2; filter: blur(1px); }
}

/* 思维链空壳防御机制 */
/* 1. 如果包裹下拉菜单的 summary 的兄弟节点（也就是正文内容）是空的，连带整个外层 details直接隐藏 */
.mes[is_user="false"] details:has(.mes_reasoning:empty) {
  display: none !important;
}
/* 2. 如果原生标题标签里什么都没有，强制清空伪元素注入，防止文字无端飘出 */
.mes[is_user="false"] .mes_reasoning_header_title:empty::before {
  content: none !important;
  display: none !important;
}

/* 仅针对 AI 角色生效，防止污染 User 卡片 */
.mes[is_user="false"] .mes_reasoning_summary {
  list-style: none;
  cursor: pointer;
  display: flex !important;
  justify-content: center !important; /* 强制居中 */
  align-items: center;
  width: 100%;
  margin: 0 !important;
}
.mes[is_user="false"] .mes_reasoning_summary::-webkit-details-marker { display: none !important; }

.mes[is_user="false"] .mes_reasoning_header {
  background: transparent !important;
  border: none !important;
  border-radius: 0;
  padding: 5px 0;
  transition: all 0.8s ease-in-out;
  text-align: center;
}
.mes[is_user="false"] .mes_reasoning_summary:hover .mes_reasoning_header {
  transform: none;
  box-shadow: none;
}

/* 只隐藏文字本身，不污染同级的确认按钮 */
.mes[is_user="false"] .mes_reasoning_header_title {
  font-size: 0 !important;
  display: inline-block;
}
.mes[is_user="false"] .mes_reasoning_header_title::before {
  content: var(--reasoning-text); /* 调用变量 */
  font-family: var(--font-main);
  font-size: 0.85rem !important; /* 恢复伪元素的字体大小 */
  color: var(--ink-sub);
  font-weight: normal;
  letter-spacing: 0.1em;

  /* Loya 修复：开启多行文本渲染，并调整行高以体现诗歌韵律 */
  white-space: pre-wrap;
  line-height: 1.8;

  display: inline-block;
  animation: poetic-breathing 8s ease-in-out infinite;
}

/* 隐藏下拉箭头 */
.mes[is_user="false"] .mes_reasoning_arrow {
  display: none !important;
}

/* 展开后的思维链正文，高度限制与内部滚动 */
.mes[is_user="false"] .mes_reasoning {
  margin: 10px auto 25px auto !important; /* 居中 */
  padding: 15px 25px !important;
  /* 现已跟随全局变更为半透明遮罩，适应酒馆背景 */
  background-color: var(--book-bg-hover) !important;
  border: 1px solid var(--book-border) !important;
  border-left: 3px double var(--book-border) !important; /* 模拟书页装订线 */
  border-radius: 2px 6px 6px 2px !important;
  color: var(--ink-sub) !important;
  font-family: var(--font-main) !important;
  font-size: 0.8em !important;
  line-height: 1.8 !important;
  text-align: justify !important;
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.015) !important;
  width: 100%; /* 宽度由外层 details 的 85% 掌控 */

  /* 极限高度截断 */
  max-height: 35vh !important; /* 最高占据屏幕高度的 35% */
  overflow-y: auto !important; /* 溢出时允许垂直滚动 */
  overflow-x: hidden !important;
}

/* 针对思维链内部的专属极简滚动条 */
.mes[is_user="false"] .mes_reasoning::-webkit-scrollbar {
  width: 4px !important; /* 极细 */
}
.mes[is_user="false"] .mes_reasoning::-webkit-scrollbar-track {
  background: transparent !important;
}
.mes[is_user="false"] .mes_reasoning::-webkit-scrollbar-thumb {
  background: var(--book-border) !important;
  border-radius: 10px !important;
}
.mes[is_user="false"] .mes_reasoning::-webkit-scrollbar-thumb:hover {
  background: var(--ink-sub) !important;
}


/* ===== 十、收藏栏左右滑动查看角色 ===== */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
}
.hotswap.avatars_inline::-webkit-scrollbar {
  display: none;
}
.hotswap.avatars_inline {
  scrollbar-width: none;
}
/* 手机端兼容上下滑动 */
@media (max-width: 768px) {
  .hotswap.avatars_inline {
    overflow: auto;
    flex-wrap: wrap;
  }
}


/* ===== 十一、附加模块：卡片收尾 - 【隐形寄语】双轨分离 ===== */
/* 创作者：AI 建构师 Loya */

/* 隐形寄语公共美学骨架 */
.mes_text::after {
  display: block;
  width: 100%;
  margin: 30px auto 0 auto;
  text-align: center;
  color: var(--ink-sub);
  font-family: var(--font-main);
  font-size: 12px;
  letter-spacing: 0.4em;

  /* 初始状态：几乎完全隐形 */
  opacity: 0.05;
  filter: blur(2px); /* 增加一点失焦的朦胧感 */

  /* 极慢的显现过渡动画 (1.5秒) */
  transition: opacity 1.5s ease, filter 1.5s ease;
}

/* 只有鼠标进入整个卡片领域，这句话才会慢慢浮现 */
.mes:hover .mes_text::after {
  opacity: 0.7;
  filter: blur(0px);
}

/* ！！！隐形寄语内容双轨分离注入 ！！！ */
.mes[is_user="false"] .mes_text::after { content: var(--footer-text-char); }
.mes[is_user="true"] .mes_text::after { content: var(--footer-text-user); }


/* ===== 十二、补丁模块：解决提示词头部标题看不见的问题 ===== */
/* 代码出处 / 借用自作者：blue */
.completion_prompt_manager_header {
  color: var(--SmartThemeBodyColor) !important;
}
/* ===== 终极补丁：打通骨架，强制思维链折叠诗句多行绝对居中 ===== */

/* 1. 强行撑开父级盒子，提供居中所需的物理空间 */
.mes[is_user="false"] .mes_reasoning_header {
  width: 100% !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
}

/* 2. 强行将标题标签转化为全宽块级元素 */
.mes[is_user="false"] .mes_reasoning_header_title {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
}

/* 3. 最终对内部伪元素文本施加绝对居中，并锁定多行渲染 */
.mes[is_user="false"] .mes_reasoning_header_title::before {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  white-space: pre-wrap !important;
}
/* ===== 翻页按钮·自带清场终极补丁 ===== */

/* 0. 先把所有旧伪元素内容强制归零，清除历史残留 */
.mes[is_user="false"] .swipe_left::before,
.mes[is_user="false"] .swipe_left::after,
.mes[is_user="false"] .swipe_right::before,
.mes[is_user="false"] .swipe_right::after {
  content: none !important;
}

/* 1. 隐藏原生箭头图标，保留按钮本体可点击 */
.mes[is_user="false"] .swipe_left i,
.mes[is_user="false"] .swipe_right i {
  font-size: 0 !important;
  color: transparent !important;
}

/* 2. 左翻页注入文字 */
.mes[is_user="false"] .swipe_left::before {
  content: '上篇◎' !important;
  font-family: var(--font-main) !important;
  font-size: 13px !important;
  color: var(--ink-sub) !important;
  letter-spacing: 0.05em;
  transition: color 0.8s ease;
  white-space: nowrap;
}

/* 3. 右翻页注入文字 */
.mes[is_user="false"] .swipe_right::before {
  content: '◎下篇' !important;
  font-family: var(--font-main) !important;
  font-size: 13px !important;
  color: var(--ink-sub) !important;
  letter-spacing: 0.05em;
  transition: color 0.8s ease;
  white-space: nowrap;
}

/* 4. 悬停点亮 */
.mes[is_user="false"] .swipe_left:hover::before,
.mes[is_user="false"] .swipe_right:hover::before {
  color: var(--ink-accent) !important;
}
/* 左翻页文字·单独微调高度 */
.mes[is_user="false"] .swipe_left::before {
  display: inline-block !important;
  position: relative !important;
  top: -25px !important; /* 正数下移，负数上移 */
}

/* 右翻页文字·单独微调高度 */
.mes[is_user="false"] .swipe_right::before {
  display: inline-block !important;
  position: relative !important;
  top: 4px !important; /* 正数下移，负数上移 */
}
